import json, re, os

def run(**kwargs):
    path = kwargs.get("path")
    pattern = kwargs.get("pattern")
    ctx = int(kwargs.get("context", 160))
    max_hits = int(kwargs.get("max_hits", 20))
    if not path or not pattern:
        return "ERR: path and pattern required"
    candidates = [path, os.path.join("missions", path), os.path.join("missions", "duskyr.com", path)]
    p = next((c for c in candidates if os.path.exists(c)), None)
    if not p:
        return f"ERR: file not found: {path} (tried {candidates})"
    with open(p, "r", encoding="utf-8", errors="replace") as f:
        raw = f.read()
    blobs = []
    try:
        obj = json.loads(raw)
        def walk(o):
            if isinstance(o, str):
                blobs.append(o)
            elif isinstance(o, dict):
                for v in o.values(): walk(v)
            elif isinstance(o, list):
                for v in o: walk(v)
        walk(obj)
    except Exception:
        blobs = [raw]
    rx = re.compile(pattern, re.I)
    out, total = [], 0
    for bi, blob in enumerate(blobs):
        for m in rx.finditer(blob):
            s = max(0, m.start()-ctx); e = min(len(blob), m.end()+ctx)
            frag = blob[s:e].replace("\\n", " ")
            out.append(f"--- hit blob#{bi} @{m.start()}: ...{frag}...")
            total += len(frag)
            if len(out) >= max_hits or total > 14000:
                out.append("[truncated]")
                return f"FILE: {p}\n" + "\n".join(out)
    if not out:
        return f"NO MATCHES for {pattern!r} in {p} (blobs={len(blobs)}, bytes={sum(len(b) for b in blobs)})"
    return f"FILE: {p}\n" + "\n".join(out)

